// Ritual spells from the Player's Guide "Ritual Descriptions" section. These
// are distinct from the regular spell lists: they are learned via the
// Ritualist talent into a ritual book and cast as rituals (no spell slot).
// Each entry carries its name, circle, source list(s), school, and text.

import type { SpellSource } from './spells'

export interface Ritual {
  name: string
  circle: number
  sources: SpellSource[]
  school: string
  text: string
}

export const RITUALS: Ritual[] = [{"name":"Alarm","circle":1,"sources":["Arcane"],"school":"Abjuration","text":"Casting Time: 1 minute Range: 30 feet Components: V, S, M (silver hand bell worth at least 10 gp) Duration: 8 hours You ward an area to alert you when intruders pass through. You set an alarm against unwanted intrusion. Choose a door, a window, or an area within range that is no larger than a 20-foot cube. Until the spell ends, an alarm alerts you when a Tiny or larger creature touches or enters the warded area. When you cast the spell, you can designate creatures that won’t set off the alarm. You also choose whether the alarm is mental or audible. A mental alarm alerts you with a ping in your mind if you are within 1 mile of the warded area. This ping awakens you if you are sleeping. An audible alarm produces the sound of a hand bell for 10 seconds within 60 feet. If you perform this ritual a second time before the duration of the first alarm spell has ended, the first alarm immediately ends."},{"name":"Animal Messenger","circle":2,"sources":["Primordial"],"school":"Enchantment","text":"Casting Time: 1 minute Range: 30 feet Components: V, S, M (a morsel of food) Duration: 24 hours You enlist the aid of a nearby beast to deliver a message for you. Choose a Tiny Beast you can see within range, such as a squirrel, blue jay, or bat. Specify a location, which you must have visited, and a recipient who matches a general description, such as “a person dressed in the uniform of the town guard” or “a red-haired dwarf wearing a pointed hat.” Then speak a message of up to twenty-five words. The Beast travels for the duration of the spell toward the specified location, covering about 50 miles per 24 hours for a flying messenger or 25 miles for other animals. When the messenger arrives, it delivers your message to the creature that you described, replicating the sound of your voice. Then the spell ends, and the Beast makes its way back to where you cast the spell. The messenger speaks only to a creature matching the description you gave. If the messenger doesn’t reach its destination before the spell ends, the message is lost, and the Beast makes its way back to where you cast this spell. If you attempt to cast this spell again while the first casting is still active, the second casting fails. At Higher Circles. As you unlock higher circles, this ritual grows in potency. Once you have access to 3rd circle spell slots or higher, the duration of the spell increases by 48 hours for each circle you have slots for above 2nd."},{"name":"Animate Dead","circle":3,"sources":["Arcane","Divine"],"school":"Necromancy","text":"Casting Time: 1 minute Range: 10 feet Components: V, S, M (a bloodstone worth at least 10 gp, which the spell consumes) Duration: Instantaneous You transform a corpse into an undead servant. This spell creates an Undead servant. Choose a pile of bones or a corpse of a Medium or Small Humanoid within range. Your spell imbues the target with a foul mimicry of life, raising it as an Undead creature. The target becomes a skeleton if you chose bones or a zombie if you chose a corpse. On each of your turns, you can use a bonus action to mentally command any creature you made with this spell if the creature is within 60 feet of you (if you control multiple creatures, you can command any or all of them at the same time, issuing the same command to each one). You decide what action the creature takes and where it moves during its next turn, or you can issue a general command, such as to guard a particular chamber or corridor. If you issue no commands, the creature only defends itself against hostile creatures. Once given an order, the creature continues to follow it until its task is complete. The creature is under your control for 24 hours, after which it stops obeying any command you’ve given it. To maintain control of the creature for another 24 hours, you must cast this spell on the creature again before the current 24-hour period ends. This use of the spell reasserts your control over a creature you have animated with this spell, rather than animating a new one. PLAYER'S GUIDE You can’t have more than 4 creatures created by this spell active at one time. If you attempt to cast this spell again while the maximum number of servants created by the first casting are still active, the servant that has been active the longest is immediately destroyed. At Higher Circles. As you unlock higher circles, this ritual grows in potency. Once you have access to 4th circle spell slots or higher, the maximum number of Undead creatures you can have active at one time increases. You can animate a maximum of two additional Undead creatures for each slot level above 3rd. Each creature must come from a different corpse or pile of bones."},{"name":"Antipathy/Sympathy","circle":8,"sources":["Arcane","Divine","Primordial","Wyrd"],"school":"Enchantment","text":"Casting Time: 1 hour Range: 60 feet Components: V, S, M (either a lump of alum soaked in vinegar for the antipathy effect or a drop of honey for the sympathy effect) Duration: 10 days You generate a semi-persistent aura that attracts or repels certain creatures. This spell attracts or repels creatures of your choice. You target something within range, either a Huge or smaller object or creature or an area that is no larger than a 200- foot cube. Then specify a kind of intelligent creature, such as red dragons, goblins, or vampires. You invest the target with an aura that either attracts or repels the specified creatures for the duration. Choose antipathy or sympathy as the aura’s effect. Antipathy. The enchantment causes creatures of the kind you designated to feel an intense urge to leave the area and avoid the target. When such a creature can see the target or comes within 60 feet of it, the creature must succeed on a WIS save or become frightened. The creature remains frightened while it can see the target or is within 60 feet of it. While frightened by the target, the creature must use its movement to move to the nearest safe spot from which it can’t see the target. If the creature moves more than 60 feet from the target and can’t see it, the creature is no longer frightened, but the creature becomes frightened again if it regains sight of the target or moves within 60 feet of it. Sympathy. The enchantment causes the specified creatures to feel an intense urge to approach the target while within 60 feet of it or able to see it. When such a creature can see the target or comes within 60 feet of it, the creature must succeed on a WIS save or use its movement on each of its turns to enter the area or move within reach of the target. When the creature has done so, it can’t willingly move away from the target. Ending the Effect. If an affected creature ends its turn while not within 60 feet of the target or able to see it, the creature makes a WIS save. On a success, the creature is no longer affected by the target and recognizes the feeling of repugnance or attraction as magical. In addition, a creature affected by the spell is allowed another WIS save every 24 hours while the spell persists. If the target damages or otherwise harms an affected creature, the affected creature can make a WIS save to end the effect. A creature that saves against this effect is immune to it for 1 minute, after which it can be affected again. If you attempt to cast this spell again while the effects of the first casting are still active, the effects of the first casting immediately end. 327"},{"name":"Arcane Lock","circle":2,"sources":["Arcane"],"school":"Abjuration","text":"Casting Time: 1 minute Range: Touch Components: V, S, M (gold dust worth at least 25 gp, which the spell consumes) Duration: Until dispelled You magically seal an entryway or container. You touch a closed door, window, gate, chest, or other entryway, and it becomes locked for the duration. You and the creatures you designate when you cast this spell can open the object normally. You can also set a password that, when spoken within 5 feet of the object, suppresses this spell for 1 minute. Otherwise, it is impassable until it is broken, or the spell is dispelled or suppressed. Casting knock on the object suppresses arcane lock for 10 minutes. While affected by this spell, the object is more difficult to break or force open; the DC to break it or pick any locks on it increases by 10."},{"name":"Arcanist’s Magic Aura","circle":2,"sources":["Arcane"],"school":"Illusion","text":"Casting Time: 1 minute Range: Touch Components: V, S, M (a small square of silk and burning incense worth at least 10 gp, which the spell consumes) Duration: 24 hours You drape your target in an illusory aura, masking its true nature. You place an illusion on a creature or an object you touch so that divination spells reveal false information about it. The target can be a willing creature or an object that isn’t being carried or worn by another creature. When you cast the spell, choose one or both of the following effects. The effect lasts for the duration. If you cast this spell on the same creature or object every day for 30 days, placing the same effect on it each time, the illusion lasts until it is dispelled. False Aura. You change the way the target appears to spells and magical effects, such as detect magic, that detect magical auras. You can make a nonmagical object appear magical, a magical object appear nonmagical, or change the object’s magical aura so that it appears to belong to a specific school of magic that you choose. When you use this effect on an object, you can make the false magic apparent to any creature that handles the item. Mask. You change the way the target appears to spells and magical effects that detect creature types, such as a paladin’s Divine Sense or the trigger of a symbol spell. You choose a creature type, and other spells and magical effects treat the target as if it were a creature of that type."},{"name":"Astral Projection","circle":9,"sources":["Arcane","Wyrd"],"school":"Necromancy","text":"Casting Time: 1 hour Range: 10 feet Components: V, S, M (for each creature you affect with this spell, you must provide one jacinth worth at least 1,000 gp and one ornately carved bar of silver worth at least 100 gp, all of which the spell consumes) Duration: Special You place yourself and several others into a deep sleep and transport your consciousnesses into the Astral Plane. You and up to eight willing creatures within range project your astral bodies into the Astral Plane (the spell fails and the casting is wasted if you are already on that plane). The material body you leave behind is unconscious and in a state of suspended animation; it doesn’t need food or air and doesn’t age. Your astral body resembles your mortal form in almost every way, replicating your game statistics and possessions. The principal difference is the addition of a silvery cord that extends from between your shoulder blades and trails behind you, fading to invisibility after 1 foot. This cord is your tether to your material body. As long as the tether remains intact, you can find your way home. If the cord is cut—something that can happen only when an effect specifically states that it does—your soul and body are separated, killing you instantly. Your astral form can freely travel through the Astral Plane and can pass through portals there leading to any other plane. If you enter a new plane or return to the plane you were on when casting this spell, your body and possessions are transported along the silver cord, allowing you to re-enter your body as you enter the new plane. Your astral form is a separate incarnation. Any damage or other effects that apply to it have no effect on your physical body, nor do they persist when you return to it. The spell ends for you and your companions when you use your action to dismiss it. When the spell ends, the affected creature returns to its physical body, and it awakens. The spell might also end early for you or one of your companions. A successful dispel magic spell used against an astral or physical body ends the spell for that creature. If a creature’s original body or its astral form drops to 0 HP, the spell ends for that creature. If the spell ends and the silver cord is intact, the cord pulls the creature’s astral form back to its body, ending its state of suspended animation. If you are returned to your body prematurely, your companions remain in their astral forms and must find their own way back to their bodies, usually by dropping to 0 HP. PLAYER'S GUIDE 328"},{"name":"Augury","circle":2,"sources":["Divine","Wyrd"],"school":"Divination","text":"Casting Time: 1 minute Range: Self Components: V, S, M (specially marked sticks, bones, or similar tokens worth at least 25 gp) Duration: Instantaneous You receive an omen about the potential outcome of your plans. By casting gem-inlaid sticks, rolling dragon bones, laying out ornate cards, or employing some other divining tool, you receive an omen from an otherworldly entity about the results of a specific course of action that you plan to take within the next 30 minutes. The GM chooses from the following possible omens: • Weal, for good results • Woe, for bad results • Weal and woe, for both good and bad results • Nothing, for results that aren’t especially good or bad The spell doesn’t take into account any possible circumstances that might change the outcome, such as the casting of additional spells or the loss or gain of a companion. If you cast the spell two or more times before completing your next long rest, there is a cumulative 25 percent chance for each casting after the first that you get a random reading. The GM makes this roll in secret."},{"name":"Awaken","circle":5,"sources":["Primordial"],"school":"Transmutation","text":"Casting Time: 8 hours Range: Touch Components: V, S, M (an agate worth at least 1,000 gp, which the spell consumes) Duration: Instantaneous You imbue a beast or plant with permanent sentience. After spending the casting time tracing magical pathways within a precious gemstone, you touch a Huge or smaller Beast or Plant. The target must have no INT or an INT of 3 (−4) or lower to be affected by this spell. The target gains INT of 10 (+0) and the ability to speak one language you know. If the target is a Plant, it gains mobility, can move its limbs, roots, vines, creepers, and so forth, and gains senses similar to a human’s. Your GM chooses statistics appropriate for the awakened Plant, such as the statistics for the awakened shrub or the awakened tree. The awakened Beast or Plant is charmed by you for 30 days or until you or your companions do anything harmful to it. When the charmed condition ends, the awakened creature chooses whether to remain friendly to you based on how you treated it while it was charmed."},{"name":"Briar Rose","circle":4,"sources":["Primordial"],"school":"Enchantment","text":"Casting Time: 1 hour Range: Touch Components: V, S, M (a rose or similar flower cut within the past 24 hours and ritual oils worth 100 gp, which the spell consumes) Duration: 10 days You imbue a flower with magic that lulls those who touch it into magical slumber. You spend an hour anointing a rose (or similar flower) with scented oils and imbuing it with potent magic, transforming it into a magic flower for the duration. The first creature other than you that touches the flower before the spell ends must make a CHA save. On a success, the flower retains its magic, and the creature can’t be affected by the flower’s magic for the next 24 hours. On a failure, the flower becomes nonmagical, the creature falls into a deep slumber for 24 hours. It can be awoken only by a greater restoration spell or similar magic, or if you choose to end the spell as an action. While slumbering, the creature doesn’t need to eat or drink, and it ceases to age. Each time the slumbering creatures takes damage, it makes a new CHA save, ending the spell on itself on a success. If you cast this spell a second time while the first magical flower is still active, the first flower becomes nonmagical. At Higher Circles. As you unlock higher circles, this ritual grows in potency. Once you have access to 6th-circle spell slots, you can increase the slumber’s duration to 7 days. Once you have access to 7th-circle spell slots, the duration can be up to 30 days. Once you have access to 8th-circle spell slots, the duration can be up to 180 days. Once you have access to 9th-circle spell slots, the duration can be up to 1 year. 329"},{"name":"Circle of Stones","circle":2,"sources":["Primordial"],"school":"Transmutation","text":"Casting Time: 1 minute Range: 30 feet (10-foot-radius circle) Components: V, S, M (four or more crystals worth at least 5 gp each) Duration: 8 hours You enchant a ring of magical crystals to attack approaching creatures. You place four crystals on the ground in an area within range that is no larger than a 10-foot-radius circle and imbue them with defensive magic. When you cast this spell, you designate any number of specific creatures or creature types to be ignored by the spell’s magic. Until the spell ends, when a creature you didn’t designate comes within 30 feet of the crystals for the first time on a turn or ends its turn there, one crystal launches itself at the intruder. The creature must succeed on a DEX save or take 1d6 magical bludgeoning damage. Once a crystal has attacked a target in this way, it becomes nonmagical and falls to the ground at the target’s feet. Even if you can’t see the crystals, you immediately know when a crystal is triggered. The spell ends when all the crystals have become nonmagical. If you cast this spell while a previous casting of circle of stones is still active, the crystals used in the first casting immediately become nonmagical, and the spell ends. At Higher Circles. As you unlock higher circles, this ritual grows in potency. Once you have access to 3rd-circle spell slots, you can affect one additional crystal for each slot you have access to above 2nd (assuming you have the components to do so)."},{"name":"Clairvoyance","circle":3,"sources":["Arcane","Divine","Wyrd"],"school":"Divination","text":"Casting Time: 10 minutes Range: 1 mile Components: V, S, M (a focus worth at least 100 gp, either a jeweled horn for hearing or a glass eye for seeing) Duration: Concentration, up to 10 minutes You conjure a small, invisible sphere through which you can spy and sense nearby locations. You create an invisible sensor within range in a location familiar to you (a place you have visited or seen before) or in an obvious location that is unfamiliar to you (such as behind a door, around a corner, or in a grove of trees). The sensor remains in place for the duration, and it can’t be attacked or otherwise interacted with. When you cast the spell, you choose seeing or hearing. You can use the chosen sense through the sensor as if you were in its space. As your action, you can switch between seeing and hearing. A creature that can see the sensor (such as a creature benefiting from see invisibility or truesight) sees a luminous, intangible orb about the size of your fist."},{"name":"Clone","circle":8,"sources":["Arcane"],"school":"Necromancy","text":"Casting Time: 1 hour Range: Touch Components: V, S, M (a diamond worth at least 1,000 gp; at least 1 cubic inch of flesh of the creature that is to be cloned, which the spell consumes; and a vessel worth at least 2,000 gp that has a sealable lid and is large enough to hold a Medium creature, such as a huge urn, coffin, mud-filled cyst in the ground, or crystal container filled with salt water) Duration: Instantaneous You create a spare body for a creature of your choice as a contingency plan. This spell grows an inert duplicate of a living creature as a safeguard against death. This clone forms inside a sealed vessel and grows to full size and maturity after 120 days; you can also choose to have the clone be a younger version of the same creature. It remains inert and endures indefinitely, as long as its vessel remains undisturbed. At any time after the clone matures, if the original creature dies, its soul transfers to the clone, provided that the soul is free and willing to return. The clone is physically identical to the original and has the same personality, memories, and abilities, but none of the original’s equipment. The original creature’s physical remains, if they still exist, become inert and can’t thereafter be restored to life, since the creature’s soul is elsewhere. If you attempt to cast this spell to create a clone of a creature that already has a clone created by this spell, the spell fails."},{"name":"Commune with Nature","circle":5,"sources":["Primordial"],"school":"Divination","text":"Casting Time: 1 minute Range: Self Components: V, S, M (a forked stick, a bowl of purified water, and a polished stone or bone of an animal native to where you are) Duration: Instantaneous You become one with nature, gaining knowledge of the surrounding territory. You must be outdoors to cast this spell. When you do so, the spell gives you knowledge of the land within 3 miles of you. In caves and other natural underground settings, the radius is limited to 300 feet. The spell doesn’t function where nature has been replaced by construction, such as in dungeons and towns. PLAYER'S GUIDE You instantly know up to three facts of your choice about any of the following subjects as they relate to the area: • Terrain and bodies of water • Prevalent plants, minerals, animals, or peoples • Powerful Celestials, Fey, Fiends, Elementals, or Undead • Influence from other planes of existence • Buildings For example, you could determine the location of powerful Undead in the area, the location of major sources of safe drinking water, and the location of any nearby towns. Once you perform this ritual, you can’t do so again until 24 hours have passed."},{"name":"Contact Other Plane","circle":5,"sources":["Arcane","Wyrd"],"school":"Divination","text":"Casting Time: 10 minutes Range: Self Components: V, M (incense or a sacrificial offering appropriate for the entity contacted worth 25 gp, which the spell consumes) Duration: 1 minute You contact a being from another plane to answer questions. You mentally contact a demigod, the spirit of a long-dead sage, or some entity from another plane. Contacting this extraplanar being can strain or even break your mind. When you cast this spell, make a DC 15 INT save. On a failure, you take 6d6 psychic damage and become incapacitated until you finish a long rest. While incapacitated in this way, you can’t take actions, can’t understand what other creatures say, can’t read, and speak only in gibberish. A greater restoration spell cast on you ends this effect. On a successful save, you can ask the entity up to five questions. You must ask your questions before the spell ends. The GM answers each question with one word, such as “yes,” “no,” “maybe,” “never,” “irrelevant,” or “unclear” (if the entity doesn’t know the answer to the question). If a one-word answer would be misleading, the GM might instead offer a short phrase as an answer. If you cast the spell two or more times before finishing your next long rest, there is a cumulative 25 percent chance for each casting that you get no answer. The GM makes this roll in secret. If you receive no answer, you can’t attempt to cast this spell again until 24 hours have passed."},{"name":"Contingency","circle":6,"sources":["Arcane"],"school":"Evocation","text":"Casting Time: 10 minutes Range: Self Components: V, S, M (a statuette of yourself carved from ivory and decorated with gems worth at least 1,500 gp) Duration: 10 days You prepare another spell to activate when certain conditions are met. Choose a spell of 5th circle or lower that you can cast, that has a casting time of 1 action, and that can target you. You cast that spell—called the contingent spell—as part of casting contingency, expending a spell slot for the contingent spell, but the contingent spell doesn’t come into effect. Instead, it takes effect when a certain circumstance occurs. You describe that circumstance when you cast the two spells. For example, a contingency cast with water breathing might stipulate that water breathing comes into effect when you are engulfed in water or a similar liquid. The contingent spell takes effect immediately after the circumstance is met for the first time, whether or not you want it to, and then contingency ends. The contingent spell takes effect only on you, even if it can normally target others. You can use only one contingency spell at a time. If you cast this spell again, the effect of another contingency spell on you ends. Also, contingency ends on you if its material component is ever not on your person."},{"name":"Control Weather","circle":8,"sources":["Divine","Primordial"],"school":"Transmutation","text":"Casting Time: 10 minutes Range: Self (5-mile radius) Components: V, S, M (burning incense and bits of earth and wood mixed in water) Duration: Concentration, up to 8 hours You command the weather to change to suit your wishes. You take control of the weather within 5 miles of you for the duration. You must be outdoors to cast this spell. Moving to a place where you don’t have a clear path to the sky ends the spell early. When you cast the spell, you change the current weather conditions, which are determined by the GM based on the climate and season. You can change precipitation, temperature, and wind. It takes 1d4 × 10 minutes for the new conditions to take effect. Once they do, you can change the conditions again. When the spell ends, the weather gradually returns to normal. When you change the weather conditions, find a current condition on the following tables and change its stage by one, up or down. When changing the wind, you can change its direction. 331 PRECIPITATION STAGE CONDITION Clear Overcast or ground fog Rain, hail, or snow Torrential precipitation (see Hazards in Chapter 6) TEMPERATURE STAGE CONDITION Extreme heat (see Hazards in Chapter 6) Hot Warm Cool Cold Extreme Cold (see Hazards in Chapter 6) WIND STAGE CONDITION Calm Moderate wind Strong wind Gale winds (see Hazards in Chapter 6)"},{"name":"Create Familiar","circle":1,"sources":["Arcane"],"school":"Transmutation","text":"Casting Time: 1 hour Range: 5 feet Components: V, S, M (a life-sized statue, puppet, stuffed animal, or other suitable vessel worth at least 10 gp, which the spell consumes) Duration: Instantaneous You gain a helpful animal pet to act as your aide and companion. As part of this ritual, you imbue your chosen vessel with a spark of your own life force to create an arcane familiar. This familiar assumes an animal form you choose from the following options: bat, cat, crab, frog (toad), hawk, lizard, octopus, owl, poisonous snake, fish (quipper), rat, raven, seahorse, spider, or weasel (see Appendix C: Creature Statistics). Upon completion of the ritual, your familiar appears in an unoccupied space within 5 feet of you. The familiar has the statistics of the chosen form, though it is considered a Construct rather than a Beast for any relevant spells or effects. Bound in Blood. When your familiar first appears, your hit point maximum decreases by one. If you permanently dismiss your familiar or it is otherwise permanently destroyed, your hit point maximum returns to normal. This reduction can’t be offset by any means as long as your familiar lives. Communicating with Your Familiar. While your familiar is on the same plane or realm of existence as you, it can magically convey what it sees or senses to you, and you can communicate with it telepathically. Controlling Your Familiar. Your familiar acts independently of you, but it always obeys your commands. In combat, it rolls its own initiative and acts on its own turn. A familiar can’t attack, but it can take other actions as normal. When you cast a spell with a range of touch, your familiar can deliver the spell as if it had cast the spell. Your familiar must be within 100 feet of you to do so, and it must use its reaction to deliver the spell when you cast it. If the spell requires an attack roll, you use your spell attack modifier for the roll. As an action, you can touch your familiar to reincorporate it into your body. When you do so, it melds into your skin, where it awaits your summons. While it is incorporated, you can use an action to expel it from your body, causing it to appear in an unoccupied space within 5 feet of you. Destroying Your Familiar. If a familiar drops to 0 HP, its body is instantly destroyed. If you still live, your familiar regrows a new body in 1 hour, regaining all its hit points and becoming active again. The new body appears in an PLAYER'S GUIDE unoccupied space within 5 feet of you. If you die, your familiar is permanently destroyed, and the ritual must be performed again to create a new familiar. At any time, you can use an action to permanently dismiss your familiar, which instantly destroys it. You can have only one familiar at a time. If you attempt to cast this spell while your current familiar still lives, the ritual fails."},{"name":"Create Undead","circle":6,"sources":["Arcane","Divine"],"school":"Necromancy","text":"Casting Time: 1 minute Range: 10 feet Components: V, S, M (one pot filled with grave dirt, one pot filled with brackish water, and one 150 gp black onyx stone for each corpse, which the spell consumes) Duration: Instantaneous You transform corpses into potent undead creatures under your command. You can cast this spell only at night. Choose up to three corpses of Medium or Small Humanoids within range. Each corpse becomes a ghoul under your control (the GM has statistics for these creatures). As a bonus action on each of your turns, you can mentally command any creature you animated with this spell if the creature is within 120 feet of you (if you control multiple creatures, you can command any or all of them at the same time, issuing the same command to each one). You decide what action the creature will take and where it will move during its next turn, or you can issue a general command, such as to guard a particular chamber or corridor. If you issue no commands, the creature only defends itself against hostile creatures. Once given an order, the creatures continues to follow it until its task is complete. The creature is under your control for 24 hours, after which it stops obeying any command you have given it. To maintain control of the creatures for another 24 hours, you must cast this spell on the creature before the current 24-hour period ends. This use of the spell reasserts your control over up to three creatures you have animated with this spell, rather than animating new ones. If you attempt to cast this spell again while Undead created by the first casting are still active, the Undead created from the first casting are no longer under your control and immediately become hostile toward you. At Higher Circles. As you unlock higher circles, this ritual grows in potency. Once you have access to 6th-circle spell slots, you can animate or reassert control over four ghouls. Once you have access to 8th-circle spell slots, you can animate or reassert control over five ghouls or two ghasts or wights. Once you have access to 9th-circle spell slots, you can animate or reassert control over six ghouls, three ghasts or wights, or two mummies."},{"name":"Creation","circle":5,"sources":["Arcane"],"school":"Illusion","text":"Casting Time: 1 minute Range: 30 feet Components: V, S, M (a tiny piece of matter of the same type of the item you plan to create) Duration: Special You transform wisps of shadow into nonliving matter that lasts for a short time. You pull wisps of shadow from the Shadow Realm to create a nonliving object or vegetable matter within range: soft goods, rope, wood, or something similar. You can also use this spell to create mineral objects such as stone, crystal, or metal. The object created must be no larger than a 5-foot cube, and the object must be of a form and material that you have seen before. The duration depends on the object’s material. If it is composed of multiple materials, use the shortest duration. CREATION MATERIALS MATERIAL DURATION MATERIAL DURATION Vegetable matter 1 day Gems 10 minutes Stone or crystal 12 hours Adamantine or mithral 1 minute Precious metals 1 hour Using any material created by this spell as another spell’s material component causes that spell to fail. If you attempt to cast this spell a second time while material created by the first casting still exists, the material created by the first casting is destroyed. At Higher Circles. As you unlock higher circles, this ritual grows in potency. Once you have access to 6th-circle spell slots, the cube increases by 5 feet for each slot you have access to above 5th."},{"name":"Detect Poison and Disease","circle":1,"sources":["Divine","Primordial"],"school":"Divination","text":"Casting Time: 1 minute Range: Self Components: V, S, M (a dried snake rattle) Duration: Concentration, up to 10 minutes You sense nearby poisons, poisonous creatures, and diseases. For the duration, you can sense the presence and location of poisons and diseases within 30 feet of you. This spell also detects the presence of creatures affected by an ongoing poison or disease, creatures that deal poison damage, and creatures that can infect other creatures with a disease, such as ghouls and mummies. You also identify the kind of poison, creature, or disease in each case. The spell can penetrate most barriers, but it is blocked by 1 foot of stone, 1 inch of common metal, a thin sheet of lead, or 3 feet of wood or dirt. 333"},{"name":"Divination","circle":4,"sources":["Divine"],"school":"Divination","text":"Casting Time: 10 minutes Range: Self Components: V, S, M (incense or a sacrificial offering appropriate for your religion worth 25 gp, which the spell consumes) Duration: 1 minute You contact a divine being to read the future or answer questions about the present. Your magic and an offering put you in contact with your deity or divine proxy. When you cast this spell, you can use it in one of the following ways: • Read the Future. You ask a single question concerning a specific goal, event, or activity to occur within 7 days. The GM offers a truthful reply. The reply might be a short phrase, a cryptic rhyme, or an omen. The spell doesn’t take into account any possible circumstances that might change the outcome, such as the casting of additional spells or the loss or gain of a companion. • Read the Present. You ask up to three questions that can be answered with a yes or no. You must ask your questions before the spell ends. You receive a correct answer for each question. Divine beings aren’t necessarily omniscient, so you might receive “unclear” as an answer if a question pertains to information that lies beyond the deity’s knowledge or pertains to future events that have not yet transpired. In a case where a one-word answer could be misleading or contrary to the deity’s interests, the GM might offer a short phrase as an answer instead to provide needed clarification. If you cast the spell two or more times before finishing your next long rest, there is a cumulative 25 percent chance for each casting that you get no answer. The GM makes this roll in secret. If you receive no answer, you can’t attempt to cast this spell again until 24 hours have passed."},{"name":"Dream","circle":5,"sources":["Arcane","Wyrd"],"school":"Illusion","text":"Casting Time: 1 minute Range: Special Components: V, S, M (a handful of sand, a dab of ink, and a writing quill plucked from a sleeping bird) Duration: 8 hours You enter a creature’s dream to shape it or deliver a message. This spell shapes a creature’s dreams. Choose a creature known to you as the target of this spell. The target must be on the same plane of existence as you. Creatures that don’t sleep, such as elves, can’t be contacted by this spell. You or a willing creature you touch enters a trance state, acting as a messenger. While in the trance, the messenger is aware of its surroundings but can’t take actions or move. If the target is asleep, the messenger appears in the target’s dreams and can converse with the target as long as it remains asleep, through the duration of the spell. The messenger can also shape the environment of the dream, creating landscapes, objects, and other images. The messenger can emerge from the trance at any time, ending the effect of the spell early. The target recalls the dream perfectly upon waking. If the target is awake when you cast the spell, the messenger knows it and can either end the trance (and the spell) or wait for the target to fall asleep, at which point the messenger appears in the target’s dreams. You can make the messenger appear monstrous and terrifying to the target. If you do, the messenger can deliver a message of no more than ten words and then the target must make a WIS save. On a failed save, echoes of the phantasmal monstrosity spawn a nightmare that lasts the duration of the target’s sleep and prevents the target from gaining any benefit from that rest. In addition, when the target wakes up, it takes 3d6 psychic damage. If you have a body part, lock of hair, clipping from a nail, or similar portion of the target’s body, the target makes its save with disadvantage. Once you cast this spell, you can’t do so again until you complete a long rest. PLAYER'S GUIDE 334"},{"name":"Fabricate","circle":4,"sources":["Arcane"],"school":"Transmutation","text":"Casting Time: 10 minutes Range: 120 feet Components: V, S Duration: Instantaneous You create fully functional, crafted objects from unworked materials. You convert raw materials into products of the same material. For example, you can fabricate a wooden bridge from a clump of trees, a rope from a patch of hemp, and clothes from flax or wool. Choose raw materials that you can see within range. You can fabricate a Large or smaller object (contained within a 10-foot cube, or eight connected 5-foot cubes), given a sufficient quantity of raw material. If you are working with metal, stone, or another mineral substance, however, the fabricated object can be no larger than Medium (contained within a single 5-foot cube). The quality of objects made by the spell is commensurate with the quality of the raw materials. Creatures or magic items can’t be created or transmuted by this spell. You also can’t use it to create items that ordinarily require a high degree of craftsmanship, such as jewelry, weapons, glass, or armor, unless you have proficiency with the type of artisan’s tools used to craft such objects. Once you cast this spell, you can’t do so again until you complete a long rest. 335"},{"name":"Find Familiar","circle":1,"sources":["Wyrd"],"school":"Conjuration","text":"Casting Time: 1 hour Range: 10 feet Components: V, S, M (charcoal, incense, and herbs collectively worth 10 gp, which the spell consumes) Duration: Instantaneous You bind a supernatural creature to serve you. You gain the service of a familiar, a spirit that takes one of the following Beast forms you choose: bat, cat, crab, frog (toad), hawk, lizard, octopus, owl, poisonous snake, fish (quipper), rat, raven, seahorse, spider, or weasel (see Appendix C: Creature Statistics). Upon completion of the ritual, your familiar appears in an unoccupied space within 10 feet of you. The familiar has the statistics of the chosen form, though it is considered a Celestial, Fey, or Fiend (your choice) rather than a Beast for any relevant spells or effects. Communicating with Your Familiar. While your familiar is on the same plane or realm of existence as you, it can magically convey what it sees or senses to you, and you can communicate with it telepathically. Controlling Your Familiar. Your familiar acts independently of you, but it always obeys your commands. In combat, it rolls its own initiative and acts on its own turn. A familiar can’t attack, but it can take other actions as normal. When you cast a spell with a range of touch, your familiar can deliver the spell as if it had cast the spell. Your familiar must be within 100 feet of you to do so, and it must use its reaction to deliver the spell when you cast it. If the spell requires an attack roll, you use your spell attack modifier for the roll. As an action, you can temporarily dismiss your familiar. It disappears into a pocket dimension where it awaits your summons. As an action while it is temporarily dismissed, you can cause it to reappear in any unoccupied space within 30 feet of you. Destroying Your Familiar. If a familiar drops to 0 HP, it disappears, leaving behind no physical form. It reappears after you cast this spell again. Alternatively, you can use an action to dismiss your familiar forever. When you do so, the next time you cast this spell, a different familiar of your choosing is summoned. You can’t have more than one familiar at a time. If you cast this spell while you already have a familiar, you instead cause it to adopt a new form. Choose a form from the familiars list. Your familiar transforms into the chosen creature."},{"name":"Find Steed","circle":2,"sources":["Divine","Primordial"],"school":"Conjuration","text":"Casting Time: 10 minutes Range: 30 feet Components: V, S Duration: Instantaneous You conjure a spirit steed and develop a bond with it as rider. You summon a spirit that assumes the form of an unusually intelligent, strong, and loyal steed, creating a long-lasting bond with it. Appearing in an unoccupied space within range, the steed takes a form that you choose: warhorse, pony, camel, elk, or mastiff. (Your GM might allow other animals to be summoned as steeds.) The steed has the statistics of its chosen form, though it is a Celestial, Fey, or Fiend (your choice) instead of its normal type. However, if the form has an INT of 5 (−3) or lower, your steed’s INT becomes 6 (−2), and it gains the ability to understand one language of your choice that you speak. Your steed serves you as a mount, both in combat and out. You have an instinctive bond that allows you to fight together as a seamless unit. While mounted on your steed, you can make any spell you cast that targets only you also target your steed. When the steed drops to 0 HP, it disappears, leaving no physical form. You can also dismiss your steed at any time as an action, causing it to disappear. In either case, casting this spell again summons the same steed, restored to its hit point maximum. While your steed is within 1 mile of you, you can communicate with it telepathically. You can’t have more than one steed bonded by this spell at a time. As an action, you can release the steed from its bond at any time, causing it to disappear."},{"name":"Find the Path","circle":6,"sources":["Primordial"],"school":"Divination","text":"Casting Time: 1 minute Range: Self Components: V, S, M (a set of divinatory tools—such as bones, ivory sticks, cards, teeth, or carved runes—worth 100 gp and an object from the location you wish to find) Duration: Concentration, up to 1 day You divine the most direct way to reach your chosen destination. This spell allows you to find the shortest, most direct physical route to a specific fixed location that you are familiar with on the same plane of existence. If you name a destination on another plane of existence, a destination that moves (such as a mobile fortress), or a destination that isn’t specific (such as “a green dragon’s lair”), the spell fails. For the duration, as long as you are on the same plane of existence as the destination, you know how far it is and in PLAYER'S GUIDE what direction it lies. While you are traveling there, when you are presented with a choice of paths along the way, you automatically determine which path is the shortest and most direct route (but not necessarily the safest route) to the destination."},{"name":"Forbiddance","circle":6,"sources":["Divine"],"school":"Abjuration","text":"Casting Time: 10 minutes Range: Touch Components: V, S, M (a sprinkling of holy water, rare incense, and powdered ruby worth at least 1,000 gp) Duration: 1 day You ward a local area against the teleportation and trespassing of extraplanar creatures. You create a ward against magical travel that protects up to 40,000 square feet of floor space to a height of 30 feet above the floor. For the duration, creatures can’t teleport into the area or use portals, such as those created by the gate spell, to enter the area. The spell proofs the area against planar travel and therefore prevents creatures from accessing the area by way of the Astral Plane, Ethereal Plane, Shadow Realm, Summerlands, or the plane shift spell. In addition, the spell damages certain types of creatures that you choose when you cast it. Choose one or more of the following: Celestials, Elementals, Fey, Fiends, Undead, and creatures with the Outsider tag. When a chosen creature enters the spell’s area for the first time on a turn or starts its turn there, the creature takes 5d10 radiant or necrotic damage (your choice when you cast this spell). When you cast this spell, you can designate a password. A creature that speaks the password as it enters the area takes no damage from the spell. The spell’s area can’t overlap with the area of another forbiddance spell. If you cast forbiddance every day for 30 days in the same location, the spell lasts until it is dispelled, and the material components are consumed on the last casting."},{"name":"Foresight","circle":9,"sources":["Arcane","Divine"],"school":"Divination","text":"Casting Time: 1 minute Range: Touch Components: V, S, M (a gilded hourglass worth at least 500 gp, which the spell consumes) Duration: 8 hours Your touch gives a creature the power to see into the future, increasing its reaction time and making it harder to hit. You touch a willing creature and bestow a limited ability to see into the immediate future. For the duration, the target can’t be surprised and has advantage on attack rolls, ability checks, and saves. In addition, other creatures have disadvantage on attack rolls against the target for the duration. This spell immediately ends if you cast it again before its duration ends. Once you target a creature with this spell, the same creature can’t gain the benefits of this spell until 7 days have passed."},{"name":"Geas","circle":5,"sources":["Arcane","Divine","Wyrd"],"school":"Enchantment","text":"Casting Time: 1 minute Range: 60 feet Components: V, M (a set of silver manacles worth 50 gp, which the spell consumes) Duration: 30 days You compel a creature to either perform a service or refrain from an activity for many days. You place a magical command on a creature that you can see within range, forcing it to carry out some service or refrain from some action or course of activity as you decide. If the creature can understand you, it must succeed on a WIS save or become charmed by you for the duration. While the creature is charmed by you, it takes 5d10 psychic damage each time it acts in a manner directly counter to your instructions, but no more than once each day. A creature that can’t understand you is unaffected by the spell. You can issue any command you choose. However, should you issue a command that would result in certain death, the spell ends. You can end the spell early by using an action to dismiss it. A remove curse, greater restoration, or wish spell also ends it. At Higher Circles. As you unlock higher circles, this ritual grows in potency. Once you have access to 7th-circle spell slots, the duration of this spell is 1 year. Once you have access to 9th-circle spell slots, the spell lasts until it is ended by one of the spells mentioned above. 337"},{"name":"Glyph of Warding","circle":3,"sources":["Arcane"],"school":"Abjuration","text":"Casting Time: 1 hour Range: Touch Components: V, S, M (incense and powdered diamond worth at least 200 gp, which the spell consumes) Duration: Until dispelled or triggered You ward a small area with a near-invisible mark that explodes or casts a spell. When you cast this spell, you inscribe a glyph that harms other creatures, either upon a surface (such as a table or a section of floor or wall) or within an object that can be closed (such as a book, a scroll, or a treasure chest) to conceal the glyph. If you choose a surface, the glyph can cover an area of the surface no larger than 10 feet in diameter. If you choose an object, that object must remain in its place; if the object is moved more than 10 feet from where you cast this spell, the glyph is broken, and the spell ends without being triggered. The glyph is nearly invisible and requires a successful INT (Investigation) check against your spell save DC to be found. You decide what triggers the glyph when you cast the spell. For glyphs inscribed on a surface, the most typical triggers include touching or standing on the glyph, removing another object covering the glyph, approaching within a certain distance of the glyph, or manipulating the object on which the glyph is inscribed. For glyphs inscribed within an object, the most common triggers include opening that object, approaching within a certain distance of the object, or seeing or reading the glyph. Once a glyph is triggered, this spell ends. You can further refine the trigger so the spell activates only under certain circumstances or according to physical characteristics (such as height or weight) or creature kind (for example, the ward could be set to affect Aberrations or drow). You can also set conditions for creatures that don’t trigger the glyph, such as those who say a certain password. When you inscribe the glyph, choose explosive runes or a spell glyph. Explosive Runes. When triggered, the glyph erupts with magical energy in a 20-foot-radius sphere centered on the glyph. The sphere spreads around corners. Each creature in the area must make a DEX save. On a failure, a creature takes 5d8 acid, cold, fire, lightning, or thunder damage (your choice when you create the glyph), or half as much damage on a success. Spell Glyph. You can store a known spell of 3rd circle or lower in the glyph by casting it as part of creating the glyph. The spell must target a single creature or an area to be stored. The spell being stored has no immediate effect when cast in this way. When the glyph is triggered, the stored spell is cast. If the spell has a target, it targets the creature that triggered the glyph. If the spell affects an area, the area is centered on that creature. If the spell summons hostile creatures or creates harmful objects or traps, they appear as close as possible to the intruder and attack it. If the spell requires concentration, it lasts until the end of its full duration. At Higher Circles. As you unlock higher circles, this ritual grows in potency. Once you have access to 4th-circle spell slots, the damage of an explosive runes glyph increases by 1d8 for each slot you have access to above 3rd. If you create a spell glyph, you can store any spell of up to the same circle as the highest circle you have access to."},{"name":"Guards and Wards","circle":6,"sources":["Arcane"],"school":"Abjuration","text":"Casting Time: 10 minutes Range: Touch Components: V, S, M (burning incense, a small measure of brimstone and oil, a knotted string, and a silver rod worth at least 10 gp) Duration: 24 hours You protect a location with bewildering effects and cunning obstacles. You create a ward that protects up to 2,500 square feet of floor space (an area 50 feet square, or one hundred 5-foot squares or twenty-five 10-foot squares). The warded area can be up to 20 feet tall and shaped as you desire. You can ward several stories of a stronghold by dividing the area among them, as long as you can walk into each contiguous area while you are casting the spell. When you cast this spell, you can specify individuals that are unaffected by any or all of the effects that you choose. You can also specify a password that, when spoken aloud, makes the speaker immune to these effects. PLAYER'S GUIDE Guards and wards creates the following effects within the warded area. Corridors. Fog fills all the warded corridors, making them heavily obscured. In addition, at each intersection or branching passage offering a choice of direction, there is a 50 percent chance that a creature other than you will believe it is going in the opposite direction from the one it chooses. Doors. All doors in the warded area are magically locked as if sealed by an arcane lock spell. In addition, you can cover up to ten doors with an illusion (equivalent to the illusory object function of the minor illusion spell) to make them appear as plain sections of wall. Stairs. Webs fill all stairs in the warded area from top to bottom, as the web spell. These strands regrow in 10 minutes if they are burned or torn away while guards and wards lasts. Other Spell Effect. You can place your choice of one of the following magical effects within the warded area: • Place dancing lights in four corridors. You can designate a simple program that the lights repeat as long as guards and wards lasts. • Place magic mouth in two locations. • Place stinking cloud in two locations. The vapors appear in the places you designate; they return within 10 minutes if dispersed by wind while guards and wards lasts. • Place a constant gust of wind in one corridor or room. • Place a suggestion in one location. You select an area of up to 5 feet square, and any creature that enters or passes through the area receives the suggestion mentally. The whole warded area radiates magic. A dispel magic cast on a specific effect, if successful, removes only that effect. You can create a permanently guarded and warded area by casting this spell there every day for one year."},{"name":"Hallow","circle":5,"sources":["Divine"],"school":"Abjuration","text":"Casting Time: 24 hours Range: Touch Components: V, S, M (herbs, oils, and incense worth at least 1,000 gp, which the spell consumes) Duration: Until dispelled You ward an area against extraplanar interlopers and give it an additional effect. You touch a point and infuse an area around it with holy (or unholy) power. The area can have a radius up to 60 feet, and the spell fails if the radius includes an area already under the effect of a hallow spell. The affected area is subject to the following effects. First, Celestials, Elementals, Fey, Fiends, Undead, and creatures with the Outsider tag can’t enter the area, nor can such creatures charm, frighten, or possess creatures within it. Any creature charmed, frightened, or possessed by such a creature is no longer charmed, frightened, or possessed upon entering the area. You can exclude one or more of those types of creatures from this effect. Second, you can bind an extra effect to the area. Choose an effect from the following list, or choose an effect offered by the GM. Some of these effects apply to creatures in the area; you can designate whether the effect applies to all creatures, creatures that follow a specific deity or leader, or creatures of a specific sort, such as orcs or trolls. When a creature that would be affected enters the spell’s area for the first time on a turn or starts its turn there, it can make a CHA save. On a success, the creature ignores the extra effect until it leaves the area. Courage. Affected creatures can’t be frightened while in the area. Darkness. Darkness fills the area. Normal light, as well as magical light created by spells of a lower circle than the slot you used to cast this spell, can’t illuminate the area. Daylight. Bright light fills the area. Magical darkness created by spells of a lower circle than the slot you used to cast this spell can’t extinguish the light. Energy Protection. Affected creatures in the area have resistance to one damage type of your choice except for bludgeoning, piercing, or slashing. Energy Vulnerability. Affected creatures in the area have vulnerability to one damage type of your choice except for bludgeoning, piercing, or slashing. Everlasting Rest. Dead bodies interred in the area can’t be turned into Undead. Extradimensional Interference. Affected creatures can’t move or travel using teleportation or by extradimensional or interplanar means. Fear. Affected creatures are frightened while in the area. Silence. No sound can emanate from within the area, and no sound can reach into it. Tongues. Affected creatures can communicate with any other creature in the area, even if they don’t share a common language."},{"name":"Hallucinatory Terrain","circle":4,"sources":["Arcane","Wyrd"],"school":"Illusion","text":"Casting Time: 10 minutes Range: 300 feet Components: V, S, M (a stone, a twig, and a bit of green plant) Duration: 24 hours You blanket an area with illusions to make it look like a different kind of natural terrain. You make natural terrain in a 150-foot cube in range look, sound, and smell like some other sort of natural terrain. Thus, open fields or a road can be made to resemble a swamp, hill, crevasse, or some other difficult or impassable terrain. A pond can be made to seem like a grassy meadow, a precipice like a gentle slope, or a rock-strewn gully 339 like a wide and smooth road. Manufactured structures, equipment, and creatures within the area aren’t changed in appearance. The tactile characteristics of the terrain are unchanged, so creatures entering the area are likely to see through the illusion. If the difference isn’t obvious by touch, a creature carefully examining the illusion can attempt an INT (Investigation) check against your spell save DC to disbelieve it. A creature who discerns the illusion for what it is sees it as a vague image superimposed on the terrain."},{"name":"Heroes’ Feast","circle":6,"sources":["Divine","Primordial"],"school":"Conjuration","text":"Casting Time: 10 minutes Range: 30 feet Components: V, S, M (a gem-encrusted bowl worth at least 1,000 gp, which the spell consumes) Duration: Instantaneous You conjure a bountiful and delicious feast that fills bellies and uplifts spirits. You bring forth a great feast, including magnificent food and drink. The feast takes 1 hour to consume and disappears at the end of that time, and the beneficial effects don’t set in until this hour is over. Up to twelve other creatures can partake of the feast. A creature that partakes of the feast gains several benefits. The creature is cured of all diseases and poison, becomes immune to poison and being frightened, and makes all WIS saves with advantage. Its hit point maximum also increases by 2d10, and it gains the same number of hit points. These benefits last for 24 hours. You must complete a long rest before you can cast this spell again."},{"name":"Identify","circle":1,"sources":["Arcane"],"school":"Divination","text":"Casting Time: 1 minute Range: Touch Components: V, S, M (a pearl worth at least 100 gp and an owl feather) Duration: Instantaneous You touch an object or a creature to learn its magical properties or any spells affecting it. You choose one object that you must touch throughout the casting of the spell. If it is a magic item or some other magic-imbued object, you learn its properties and how to use them, whether it requires attunement to use, and how many charges it has, if any. You learn whether any spells are affecting the item and what they are. If the item was created by a spell, you learn which spell created it. If you instead touch a creature throughout the casting, you learn what spells, if any, are currently affecting it."},{"name":"Illusory Script","circle":1,"sources":["Arcane","Wyrd"],"school":"Illusion","text":"Casting Time: 1 minute Range: Touch Components: V, S, M (a lead-based ink worth at least 10 gp, which the spell consumes) Duration: 10 days You scribe an illusion of false, hidden, or indiscernible script. You write on parchment, paper, or some other suitable writing material and imbue it with a potent illusion that lasts for the duration. To you and any creatures you designate when you cast the spell, the writing appears normal, written in your hand, and conveys whatever meaning you intended when you wrote the text. To all others, the writing appears as if it were written in an unknown or magical script that is unintelligible. Alternatively, you can cause the writing to appear to be an entirely different message, written in a different hand and language, though the language must be one you know. If the spell is dispelled, the original script and the illusion both disappear. A creature with truesight can read the hidden message."},{"name":"Imprisonment","circle":9,"sources":["Arcane","Wyrd"],"school":"Abjuration","text":"Casting Time: 1 minute Range: 30 feet Components: V, S, M (a vellum depiction or a carved statuette in the likeness of the target and a special component that varies according to the version of the spell you choose worth at least 500 gp per hit die of the target) Duration: Until dispelled You place a creature in a nigh-inescapable magical prison. You create a magical restraint to hold a creature that you can see within range. The target must succeed on a WIS save or be bound by the spell; if it succeeds, it is immune to this spell if you cast it again. While affected by this spell, the creature doesn’t need to breathe, eat, or drink, and it doesn’t age. Divination spells can’t locate or perceive the target. When you cast the spell, you choose one of the following forms of imprisonment. Burial. The target is entombed far beneath the earth in a sphere of magical force that is just large enough to contain the target. Nothing can pass through the sphere, nor can any creature teleport or use planar travel to get into or out of it. The special component for this version of the spell is a small mithral orb. Chaining. Heavy chains, firmly rooted in the ground, hold the target in place. The target is restrained until the spell ends, and it can’t move or be moved by any means until then. PLAYER'S GUIDE The special component for this version of the spell is a fine chain of precious metal. Hedged Prison. The spell transports the target into a tiny demiplane that is warded against teleportation and planar travel. The demiplane can be a labyrinth, a cage, a tower, or any similar confined structure or area of your choice. The special component for this version of the spell is a miniature representation of the prison made from jade. Minimus Containment. The target shrinks to a height of 1 inch and is imprisoned inside a gemstone or similar object. Light can pass through the gemstone normally (allowing the target to see out and other creatures to see in), but nothing else can pass through, even by means of teleportation or planar travel. The gemstone can’t be cut or broken while the spell remains in effect. The special component for this version of the spell is a large, transparent gemstone such as a corundum, diamond, or ruby. Slumber. The target falls asleep and can’t be awoken. The special component for this version of the spell consists of rare soporific herbs. Ending the Spell. During the casting of the spell, in any of its versions, you can specify a condition that will cause the spell to end and release the target. The condition can be as specific or as elaborate as you choose, but the GM must agree that the condition is reasonable and has a likelihood of coming to pass. The conditions can be based on a creature’s name, identity, or deity but otherwise must be based on observable actions or qualities and not based on intangibles such as level, CR, class, or hit points. A dispel magic spell can end the spell only if it is cast as a 9th-circle spell, targeting either the prison or the special component used to create it. You can use a particular special component to create only one prison at a time. If you cast the spell again using the same component, the target of the first casting is immediately freed from its binding."},{"name":"Instant Summons","circle":6,"sources":["Arcane"],"school":"Conjuration","text":"Casting Time: 1 minute Range: Touch Components: V, S, M (a sapphire worth 1,000 gp) Duration: Until dispelled You mystically mark an object, allowing you to summon it to your hand from any distance or plane. You touch an item weighing 10 pounds or less whose longest dimension is 6 feet or less. The spell leaves an invisible mark on its surface and invisibly inscribes the name of the item on the sapphire you use as the material component. Each time you cast this spell, you must use a different sapphire. At any time thereafter, you can use your action to speak the item’s name and crush the sapphire, destroying it. The item instantly appears in your hand regardless of physical or planar distances, and the spell ends. If another creature is holding or carrying the item, crushing the sapphire doesn’t transport the item to you, but instead you learn who the creature possessing the item is and roughly where that creature is located at that moment. Dispel magic or a similar effect successfully applied to the sapphire ends this spell’s effect."},{"name":"Locate","circle":2,"sources":["Arcane","Divine","Primordial","Wyrd"],"school":"Divination","text":"Casting Time: 1 minute Range: Self (1 mile) Components: V, S, M (a figurine of a bloodhound worth at least 25 gp, which the spell consumes) Duration: Concentration, up to 10 minutes You discern the direction and distance of desired objects or creatures. Describe or name a particular kind of object (such as a certain kind of apparel, jewelry, tool, or weapon) or particular kind of creature (such as a human or a unicorn). If a suitable target is within range of the spell, you sense the direction to the nearest creature or object within the spell’s range. If the target is moving, you know the direction of its movement. This spell can’t locate a creature or object if it in is a different form, such as being under the effects of a polymorph spell, or if the target is shielded by an effect that blocks divination magic, like the nondetection spell. You can only have a single casting of locate active on yourself at one time. If you cast this spell a second time, the first casting immediately ends. At Higher Circles. As you unlock higher circles, this ritual grows in potency. Once you have access to 4th-circle spell slots, you can use this spell to locate a specific creature or object that is familiar to you. In addition, the duration of this spell increases to concentration, up to 1 hour. 341"},{"name":"Magic Circle","circle":3,"sources":["Arcane","Divine","Wyrd"],"school":"Abjuration","text":"Casting Time: 1 minute Range: 10 feet Components: V, S, M (holy water or powdered silver and iron worth at least 100 gp, which the spell consumes) Duration: 1 hour You circle a small location with warding magic and arcane runes, barring access for certain foes. You create a 10-foot-radius, 20-foot-tall cylinder of magical energy centered on a point on the ground that you can see within range. Glowing runes appear wherever the cylinder intersects with the floor or other surface. Choose one or more of the following types of creatures: Celestials, Elementals, Fey, Fiends, or Undead. The circle affects a creature of the chosen type in the following ways: • The creature can’t willingly enter the cylinder by nonmagical means. If the creature tries to use teleportation or interplanar travel to do so, it must first succeed on a CHA save. • The creature has disadvantage on attack rolls against targets within the cylinder. • Targets within the cylinder can’t be charmed, frightened, or possessed by the creature. When you cast this spell, you can elect to cause its magic to operate in the reverse direction, preventing a creature of the specified type from leaving the cylinder and protecting targets outside it. At Higher Circles. As you unlock higher circles, this ritual grows in potency. Once you have access to 4th-circle spell slots, the duration increases by 1 hour for each slot you have access to above 3rd."},{"name":"Magic Jar","circle":6,"sources":["Wyrd"],"school":"Necromancy","text":"Casting Time: 1 minute Range: Self Components: V, S, M (a gem, crystal, or ornamental container worth at least 500 gp) Duration: Until dispelled You place your soul in a magic container, allowing you to possess a different creature and trap their soul in the process. Your body falls into a catatonic state as your soul leaves it and enters the container you used for the spell’s material component. While your soul inhabits the container, you are aware of your surroundings as if you were in the container’s space. You can’t move or use reactions. The only action you can take is to project your soul up to 100 feet out of the container, either returning to your living body (and ending the spell) or attempting to possess a humanoid’s body. You can attempt to possess any Humanoid within 100 feet of you that you can see (creatures warded by a protection from evil and good or magic circle spell can’t be possessed). The target must make a CHA save. On a failure, your soul moves into the target’s body, and the target’s soul becomes trapped in the container. On a success, the target resists your efforts to possess it, and you can’t attempt to possess it again for 24 hours. Once you possess a creature’s body, you control it. Your game statistics are replaced by the statistics of the creature, though you retain your personality and your INT, WIS, and CHA scores. You retain the benefit of your own class features. If the target has any class levels, you can’t use any of its class features. Meanwhile, the possessed creature’s soul can perceive from the container using its own senses, but it can’t move or take actions at all. While possessing a body, you can use your action to return from the host body to the container if it is within 100 feet of you, returning the host creature’s soul to its body. If the host body dies while you’re in it, the creature dies, and you must make a CHA save against your own spellcasting DC. On a success, you return to the container if it is within 100 feet of you. Otherwise, you die. If the container is destroyed or the spell ends, your soul immediately returns to your body. If your body is more than 100 feet away from you or if your body is dead when you attempt to return to it, you die. If another creature’s soul is in the container when it is destroyed, the creature’s soul returns to its body if the body is alive and within 100 feet. Otherwise, that creature dies. When the spell ends, the container is destroyed."},{"name":"Magic Mouth","circle":2,"sources":["Arcane","Wyrd"],"school":"Illusion","text":"Casting Time: 10 minutes Range: 30 feet Components: V, S, M (a small bit of honeycomb and jade dust worth at least 10 gp, which the spell consumes) Duration: Until dispelled You enchant an object to deliver a short message when the time is right. You implant a message within an object in range, a message that is uttered when a trigger condition is met. Choose an object that you can see and that isn’t being worn or carried by another creature. Then speak the message, which must be twenty-five words or fewer, though it can be delivered over as long as 10 minutes. Finally, determine the circumstance that will trigger the spell to deliver your message. When that circumstance occurs, a magical mouth appears on the object and recites the message in your voice and at the same volume you spoke. If the object you chose has a mouth or something that looks like a mouth (for example, the mouth of a statue), the magical mouth appears there so that the words appear to come from the object’s mouth. PLAYER'S GUIDE When you cast this spell, you can have the spell end after it delivers its message, or it can remain and repeat its message when the trigger occurs. The triggering circumstance can be as general or as detailed as you like, though it must be based on visual or audible conditions that occur within 30 feet of the object. For example, you could instruct the mouth to speak when any creature moves within 30 feet of the object or when a silver bell rings within 30 feet of it."},{"name":"Magnificent Mansion","circle":7,"sources":["Arcane","Wyrd"],"school":"Conjuration","text":"Casting Time: 10 minutes Range: 300 feet Components: V, S, M (a miniature portal carved from ivory, a small piece of polished marble, and a tiny silver spoon, each item worth at least 5 gp) Duration: 24 hours You conjure an extradimensional mansion, fully stocked with food and staffed with invisible servants. You conjure an extradimensional dwelling in range that lasts for the duration. You choose where its one entrance is located. The entrance shimmers faintly and is 5 feet wide and 10 feet tall. You and any creature you designate when you cast the spell can enter the extradimensional dwelling as long as the portal remains open. You can open or close the portal if you are within 30 feet of it. While closed, the portal is invisible. Beyond the portal is a magnificent foyer with numerous chambers beyond. The atmosphere is clean, fresh, and warm. You can create any floor plan you like, but the space can’t exceed 50 cubes, each cube being 10 feet on each side. The place is furnished and decorated as you choose. It contains sufficient food to serve a nine-course banquet for up to one hundred people. A staff of one hundred near- transparent servants attends all who enter. You decide the visual appearance of these servants and their attire. They are completely obedient to your orders. Each servant can perform any task a normal human servant could perform, but they can’t attack or take any action that would directly harm another creature. Thus, the servants can fetch things, clean, mend, fold clothes, light fires, serve food, pour wine, and so on. The servants can go anywhere in the mansion but can’t leave it. Furnishings and other objects created by this spell dissipate into smoke if removed from the mansion. When the spell ends, any creatures inside the extradimensional space are expelled into the open spaces nearest to the entrance."},{"name":"Metamorphosis","circle":9,"sources":["Primordial"],"school":"Transmutation","text":"Casting Time: 10 minutes Range: Touch Components: V, S, M (raw silk worth 1,000 gp, which the spell consumes) Duration: Instantaneous You permanently transform a willing creature’s physical characteristics. You touch a willing creature and transform it in one of the following four ways (the target must agree with the option you choose): • If the creature is Humanoid, you can change its lineage to any other lineage you choose. It loses any traits and abilities associated with its former lineage and gains any traits and abilities of the new lineage. • You can lower one of its ability scores by 2 (modifier decreases by −1) and increase a different ability score by 2 (modifier increases by +1), to a maximum of 20. • You give the creature birdlike or batlike wings. It gains a flying speed of 30 feet. Alternatively, you can remove its wings, which takes away an existing flying speed. You might be able to achieve a different effect of a similar kind with the permission of your GM. A creature can be affected by this spell only once a year. If the spell is cast on it again before a year has passed, the casting fails."},{"name":"Mirage Arcane","circle":7,"sources":["Arcane","Wyrd"],"school":"Illusion","text":"Casting Time: 10 minutes Range: Sight Components: V, S Duration: 10 days You grant an illusory appearance to a huge swath of terrain. You make terrain in an area up to 1 mile square look, sound, smell, and even feel like some other sort of terrain. The terrain’s general shape remains the same, however. Open fields or a road could be made to resemble a swamp, hill, crevasse, or some other difficult or impassable terrain. A pond can be made to seem like a grassy meadow, a precipice like a gentle slope, or a rock-strewn gully like a wide and smooth road. Similarly, you can alter the appearance of structures in the area or add them where none are present. The spell doesn’t disguise, conceal, or add creatures. The illusion includes audible, visual, tactile, and olfactory elements, so it can turn clear ground into difficult terrain (or vice versa) or otherwise impede movement through the area. Any piece of the illusory terrain (such as a rock or stick) that is removed from the spell’s area disappears immediately. 343 Creatures with truesight can see through the illusion to the terrain’s true form; however, all other elements of the illusion remain, so while the creature is aware of the illusion’s presence, the creature can still physically interact with the illusion."},{"name":"Oculus Blossoms","circle":7,"sources":["Primordial"],"school":"Divination","text":"Casting Time: 1 minute Range: 60 feet Components: V, S, M (a seed or bulb carved with the image of an eye) Duration: 24 hours You plant several magic flowers; you can hear and see through them. You cause up to five Tiny magical flowers to sprout in spaces you can see within range. The spaces you select must contain an area suitable for supporting a living plant, such as a patch of open ground, a pot of dirt, or similar. The flowers that appear are always of a type native to the area and at a glance are indistinguishable from nonmagical flowers. Until the spell ends, you can use an action to see and hear through any of the flowers as if you were standing in their space. You can do so no matter how far away you are from the flowers as long as you and the flowers are on the same plane of existence. While perceiving through a flower, you can use a bonus action to switch your senses to a different flower or end the effect. Creatures that can see invisible things via spells like see invisibility or features like truesight see a luminous, intangible eye in place of a blossom when they look at a flower created by this spell. If you attempt to cast this spell a second time while flowers from the first casting are still active, the flowers from the first casting are immediately destroyed. At Higher Circles. As you unlock higher circles, this ritual grows in potency. Once you have access to 8th-circle spell slots, the duration increases to 7 days. Once you have access to 9th-circle spell slots, the duration is 30 days."},{"name":"Phantom Steed","circle":3,"sources":["Wyrd"],"school":"Illusion","text":"Casting Time: 1 minute Range: 30 feet Components: V, S, M (an apple made of gold worth 5 gp) Duration: 1 hour You conjure a ghostly mount that can run at incredible speed for a short time. A Large, quasi-real, horse-like creature appears on the ground in an unoccupied space of your choice within range. You decide the creature’s appearance, but it is equipped with a saddle, bit, and bridle. Any of the equipment created by the spell vanishes in a puff of smoke if it is ever more than 10 feet away from the steed. PLAYER'S GUIDE For the duration, you or a creature you choose can ride the steed. The creature uses the statistics for a riding horse, except it has a speed of 100 feet and can travel 10 miles in an hour, or 13 miles at a fast pace. When the spell ends, the steed gradually fades, giving the rider 1 minute to dismount. The spell ends if you use an action to dismiss it, if the steed takes any damage, or if you use this spell to summon a different steed."},{"name":"Planar Ally","circle":6,"sources":["Divine","Wyrd"],"school":"Conjuration","text":"Casting Time: 10 minutes Range: 60 feet Components: V, S Duration: Instantaneous You chant the names and praises of an extraplanar creature to bargain for their support and services. You beseech an otherworldly entity for aid. The being must be known to you: a god, a demon prince, or some other being of cosmic power. That entity sends a Celestial, an Elemental, or a Fiend loyal to it to aid you, making the creature appear in an unoccupied space within range. If you know a specific creature’s name, you can speak that name when you cast this spell to request that creature, though you might get a different creature anyway (GM’s choice). When the creature appears, it is under no compulsion to behave in any particular way. You can ask the creature to perform a service in exchange for payment, but it isn’t obliged to do so. The requested task could range from simple (“fly us across the chasm,” or “help us fight a battle”) to complex (“spy on our enemies,” or “protect us during our foray into the dungeon”). You must be able to communicate with the creature to bargain for its services. Payment can take a variety of forms. A Celestial might require a sizable donation of gold or magic items to an allied temple, while a Fiend might demand a living sacrifice or a gift of treasure. Some creatures might exchange their service for a quest undertaken by you. As a rule of thumb, a task that can be measured in minutes requires a payment worth 100 gp per minute. A task measured in hours requires 1,000 gp per hour. And a task measured in days (up to 10 days) requires 10,000 gp per day. The GM can adjust these payments based on the circumstances under which you cast the spell. If the task is aligned with the creature’s ethos, the payment might be halved or even waived. Nonhazardous tasks typically require only half the suggested payment, while especially dangerous tasks might require a greater gift. Creatures rarely accept tasks that would cause them harm. After the creature completes the task or when the agreed‑upon duration of service expires, the creature returns to its home plane after reporting back to you (if appropriate to the task and if possible). If you are unable to agree on a price for the creature’s service, the creature immediately returns to its home plane. You can’t have more than one ally at any one time. Once you cast this spell, you can’t beseech the same entity with another casting of this spell until 7 days have passed. 345"},{"name":"Planar Binding","circle":5,"sources":["Arcane","Divine","Wyrd"],"school":"Abjuration","text":"Casting Time: 1 hour Range: 60 feet Components: V, S, M (a jewel worth at least 1,000 gp, which the spell consumes) Duration: 24 hours You bind an extraplanar creature into your service. You attempt to bind a Celestial, an Elemental, a Fey, or a Fiend into your service. The creature must be within range for the entire casting of the spell. Typically, the creature is first summoned into the center of an inverted magic circle in order to keep it trapped while this spell is cast. At the completion of the casting, the target must make a CHA save. On a failed save, it is bound to serve you for the duration. If the creature was summoned or created by another spell, that spell’s duration is extended to match the duration of this spell. A bound creature must follow your instructions to the best of its ability. You might command the creature to accompany you on an adventure, to guard a location, or to deliver a message. The creature obeys the letter of your instructions, but if the creature is hostile to you, it strives to twist your words to achieve its own objectives. If the creature carries out your instructions completely before the spell ends, it travels to you to report this fact if you are on the same plane of existence. If you are on a different plane of existence, it returns to the place where you bound it and remains there until the spell ends. At Higher Circles. As you unlock higher circles, this ritual grows in potency. Once you have access to 6th-circle spell slots, the duration increases to 10 days. Once you have access to 7th-circle spell slots the duration is 30 days. Once you have access to 8th-circle spell slots, the duration is 180 days. Once you have access to 9th-circle spell slots, the duration is 1 year."},{"name":"Prayer of Healing","circle":2,"sources":["Divine"],"school":"Necromancy","text":"Casting Time: 10 minutes Range: 30 feet Components: V Duration: Instantaneous You heal a large group of creatures. Up to six creatures of your choice that you can see within range each regain hit points equal to 2d8 + your spellcasting ability modifier. This spell has no effect on Constructs or Undead. Once you cast this spell, you can’t do so again until you complete a long rest. At Higher Circles. As you unlock higher circles, this ritual grows in potency. Once you have access to 3rd-circle spell slots or higher, the healing increases by 1d8 for each slot above 3rd."},{"name":"Private Sanctum","circle":4,"sources":["Arcane","Divine"],"school":"Abjuration","text":"Casting Time: 10 minutes Range: 120 feet Components: V, S, M (a thin sheet of lead, a piece of opaque glass, a wad of cloth, and powdered chrysolite) Duration: 24 hours You magically secure an area with magical tricks and defensive properties. You make an area within range magically secure. The area is a cube that can be as small as 5 feet to as large as 100 feet on each side. The spell lasts for the duration or until you use an action to dismiss it. When you cast the spell, you decide what sort of security the spell provides, choosing any or all of the following properties: • Sounds can’t pass through the barrier at the edge of the warded area. • The barrier of the warded area appears dark and foggy, preventing vision (including darkvision) through it. • Sensors created by divination spells can’t appear inside the protected area or pass through the barrier at its perimeter. • Creatures in the area can’t be targeted by divination spells. • Nothing can teleport into or out of the warded area. • Planar travel is blocked within the warded area. Casting this spell on the same spot every day for a year makes this effect permanent. If you attempt to cast this spell a second time while the first casting is active, the effects of the first spell immediately end. At Higher Circles. When you cast this spell using a spell slot of 5th circle or higher, you can increase the size of the cube by 100 feet for each slot you have access to above 4th. Thus, you could protect a cube that can be up to 200 feet on one side once you have access to 5th-circle spell slots. PLAYER'S GUIDE 346"},{"name":"Purify Food and Drink","circle":1,"sources":["Divine","Primordial"],"school":"Transmutation","text":"Casting Time: 1 minute Range: 10 feet Components: V, S Duration: Instantaneous You cleanse food and drink for safe consumption. All nonmagical food and drink within a 5-foot-radius sphere centered on a point of your choice within range is purified and rendered free of poison and disease."},{"name":"Raise Dead","circle":5,"sources":["Divine"],"school":"Necromancy","text":"Casting Time: 1 hour Range: Touch Components: V, S, M (a diamond worth at least 500 gp, which the spell consumes) Duration: Instantaneous You return a creature that has died in the past ten days to life. You return a dead creature you touch to life, provided that it has been dead no longer than 10 days. If the creature’s soul is both willing and at liberty to rejoin the body, the creature returns to life with 1 HP. This spell also neutralizes any poisons and cures nonmagical diseases that affected the creature at the time it died. This spell doesn’t, however, remove magical diseases, curses, or similar effects; if these aren’t first removed prior to casting the spell, they take effect when the creature returns to life. The spell can’t return an Undead creature to life. This spell closes all mortal wounds, but it doesn’t restore missing body parts. If the creature is lacking body parts or organs integral for its survival—its head, for instance—the spell automatically fails. Coming back from the dead is an ordeal. The target takes a −4 penalty to all attack rolls, saves, and ability checks. Every time the target finishes a long rest, the penalty is reduced by 1 until it disappears."},{"name":"Regenerate","circle":7,"sources":["Divine","Primordial"],"school":"Transmutation","text":"Casting Time: 1 minute Range: Touch Components: V, S, M (a prayer wheel or an intact sleeve of snakeskin and holy water) Duration: 1 hour You slowly heal a creature you touch, restoring hit points and severed limbs. You touch a creature and stimulate its natural healing ability. The target regains 4d8 + 15 hit points. For the duration of the spell, the target regains 1 HP at the start of each of its turns (10 HP each minute). The target’s severed body members (fingers, legs, tails, and so on), if any, are restored after 2 minutes. If you have the severed part and hold it to the stump, the spell instantaneously causes the limb to knit to the stump. Once you cast this spell, you can’t do so again until you complete a long rest."},{"name":"Reincarnate","circle":5,"sources":["Primordial"],"school":"Transmutation","text":"Casting Time: 1 hour Range: Touch Components: V, S, M (rare oils and unguents worth at least 1,000 gp, which the spell consumes) Duration: Instantaneous This long ritual brings a dead soul back to life in a completely new body. You touch a dead Humanoid or a piece of a dead Humanoid. Provided that the creature has been dead no longer than 10 days, the spell forms a new adult body for it and then calls the soul to enter that body. If the target’s soul isn’t free or willing to do so, the spell fails. The magic fashions a new body for the creature to inhabit, which likely causes the creature’s lineage to change. The GM rolls a d100 and consults the Reincarnation Bodies table to determine what form the creature takes when restored to life, or the GM chooses a form. The reincarnated creature recalls its former life and experiences. It retains the capabilities it had in its original form, except it exchanges its original lineage for the new one and changes its lineage traits accordingly. REINCARNATION BODIES d100 LINEAGE 01–04 Beastkin, Avian 05–08 Beastkin, Agile 09–10 Beastkin, Aquatic 11–13 Beastkin, Sturdy 14–24 Dwarf 25–36 Elf 37–58 Human 59–62 Kobold 63–64 Kobold, Truescale 65–69 Orc 70–75 Syderean, Celestial 76–81 Syderean, Fiendish 82–93 Smallfolk, Gnome 94–00 Smallfolk, Halfling 347"},{"name":"Resurrection","circle":7,"sources":["Divine"],"school":"Necromancy","text":"Casting Time: 1 hour Range: Touch Components: V, S, M (a diamond worth at least 1,000 gp, which the spell consumes) Duration: Instantaneous You work a miracle, bringing a soul whose end came too soon back from the dead. You touch a dead creature that has been dead for no more than a century, that didn’t die of old age, and that isn’t Undead. If its soul is free and willing, the target returns to life with all its hit points. This spell neutralizes any poisons and cures normal diseases afflicting the creature when it died. It doesn’t, however, remove magical diseases, curses, and the like; if such effects aren’t removed prior to casting the spell, they afflict the target on its return to life. This spell closes all mortal wounds and restores any missing body parts. Coming back from the dead is an ordeal. The target takes a −4 penalty to all attack rolls, saves, and ability checks. Every time the target finishes a long rest, the penalty is reduced by 1 until it disappears. Casting this spell to restore life to a creature that has been dead for one year or longer taxes you greatly. Until you finish a long rest, you can’t cast spells again, and you have disadvantage on all attack rolls, ability checks, and saves."},{"name":"Scrying","circle":5,"sources":["Arcane","Divine"],"school":"Divination","text":"Casting Time: 10 minutes Range: Self Components: V, S, M (a focus worth at least 1,000 gp such as a crystal ball, a silver mirror, or a font filled with holy water) Duration: Concentration, up to 10 minutes You can spy on a particular creature or location. You can see and hear a particular creature you choose that is on the same plane of existence as you. The target must make a WIS save, the DC for which is modified by how well you know the target and the sort of physical connection you have to it. If a target knows you’re casting this spell, it can fail the save voluntarily if it wants to be observed. WISDOM SAVE MODIFER KNOWLEDGE SAVE DC MODIFIER Secondhand (you have heard of the target) +5 Firsthand (you have met the target) +0 Familiar (you know the target well) −5 CONNECTION SAVE DC MODIFIER Likeness or picture −2 Possession or garment −4 Body part, lock of hair, bit of nail, or the like −10 On a successful save, the target isn’t affected, and you can’t use this spell against it again for 24 hours. On a failed save, the spell creates an invisible sensor within 10 feet of the target. You can see and hear through the sensor as if you were there. The sensor moves with the target, remaining within 10 feet of it for the duration. A creature that can see invisible objects sees the sensor as a luminous orb about the size of your fist. Instead of targeting a creature, you can choose a location you have seen before as the target of this spell. When you do, the sensor appears at that location and doesn’t move. PLAYER'S GUIDE 348"},{"name":"Secret Chest","circle":4,"sources":["Arcane","Wyrd"],"school":"Abjuration","text":"Casting Time: 1 minute Range: Touch Components: V, S, M (an exquisite chest, 3 feet by 2 feet by 2 feet, constructed from rare materials worth at least 5,000 gp and a Tiny replica made from the same materials worth at least 50 gp) Duration: Instantaneous You conceal a chest on the Ethereal Plane, which you can access and send back as needed. You hide a chest and all its contents on the Ethereal Plane. You must touch the chest and the miniature replica that serves as a material component for the spell. The chest can contain up to 12 cubic feet of nonliving material (3 feet by 2 feet by 2 feet). While the chest remains on the Ethereal Plane, you can use an action and touch the replica to recall the chest. It appears in an unoccupied space on the ground within 5 feet of you. You can send the chest back to the Ethereal Plane by using an action and touching both the chest and the replica. After 60 days, there is a cumulative 5 percent chance per day that the spell’s effect ends. This effect ends if you cast this spell again, if the smaller replica chest is destroyed, or if you choose to end the spell as an action. If the spell ends and the larger chest is on the Ethereal Plane, it is irretrievably lost. If you attempt to cast this spell while a chest from a previous casting is still active, the spell fails."},{"name":"Simulacrum","circle":7,"sources":["Arcane"],"school":"Illusion","text":"Casting Time: 12 hours Range: Touch Components: V, S, M (snow or ice in quantities sufficient to make a life-size copy of the duplicated creature; some hair, fingernail clippings, or other piece of that creature’s body placed inside the snow or ice; and powdered ruby worth 1,500 gp sprinkled over the duplicate, which the spell consumes) Duration: Until dispelled You create a facsimile of a creature from snow, bits of hair, and crystalline dust. You shape an illusory duplicate of one Beast or Humanoid that is within range for the entire casting time of the spell. The duplicate is a creature, partially real and formed from ice or snow, and it can take actions and otherwise be affected as a normal creature. It appears to be the same as the original, but it has half the creature’s hit point maximum and is formed without any equipment. Otherwise, the illusion uses all the statistics of the creature it duplicates. The simulacrum is friendly to you and creatures you designate. It obeys your spoken commands, moving and acting in accordance with your wishes and acting on your turn in combat. The simulacrum lacks the ability to learn or become more powerful, so it never increases its level or other abilities, nor can it regain expended spell slots. If the simulacrum is damaged, you can repair it in an alchemical laboratory using rare herbs and minerals worth 100 gp per hit point it regains. The simulacrum lasts until it drops to 0 HP, at which point it reverts to snow and melts instantly. If you cast this spell again, any currently active duplicates you created with this spell are instantly destroyed. 349"},{"name":"Song of the Forest","circle":4,"sources":["Primordial"],"school":"Transmutation","text":"Casting Time: 10 minutes Range: Self Components: V, S, M (a dried leaf, crumpled and released) Duration: Concentration, up to 10 minutes Your senses become supernaturally keen, so you can perceive near- inaudible sounds. You attune your senses to the natural world so that you can detect every sound that occurs within 60 feet of you. You can clearly picture the source of each sound in your mind. While the spell is active, you have tremorsense to a range of 10 feet, darkvision to a range of 30 feet, and you have advantage on WIS (Perception) checks. Once you cast this spell, you can’t do so again until you complete a long rest."},{"name":"Speak with Dead","circle":3,"sources":["Divine","Wyrd"],"school":"Necromancy","text":"Casting Time: 1 minute Range: 10 feet Components: V, S, M (burning incense) Duration: 10 minutes You bestow sentience on a corpse long enough to ask it five questions. You grant the semblance of life and intelligence to a corpse of your choice within range, allowing it to answer the questions you pose. The corpse must still have a mouth and can’t be Undead. The spell fails if the corpse was the target of this spell within the last 10 days. Until the spell ends, you can ask the corpse up to five questions. The corpse knows only what it knew in life, including the languages it knew. Answers are usually brief, cryptic, or repetitive, and the corpse is under no compulsion to offer a truthful answer if you are hostile to it or it recognizes you as an enemy. This spell doesn’t return the creature’s soul to its body, only its animating spirit. Thus, the corpse can’t learn new information, doesn’t comprehend anything that has happened since it died, and can’t speculate about future events. Once you target a particular corpse with this spell, you can never cast this ritual on that particular corpse again."},{"name":"Symbol","circle":7,"sources":["Arcane"],"school":"Abjuration","text":"Casting Time: 1 action Range: Touch Components: V, S, M (mercury, phosphorus, and powdered diamond and opal with a total value of at least 1,000 gp, which the spell consumes) Duration: Until dispelled or triggered You inscribe a nigh-invisible glyph to ward something or some place with a potent effect of your choice. When you cast this spell, you inscribe a harmful glyph either on a surface (such as a section of floor, a wall, or a table) or within an object that can be closed to conceal the glyph (such as a book, a scroll, or a treasure chest). If you choose a surface, the glyph can cover an area of the surface no larger than 10 feet in diameter. If you choose an object, that object must remain in its place; if the object is moved more than 10 feet from where you cast this spell, the glyph is broken, and the spell ends without being triggered. The glyph is nearly invisible, requiring an INT (Investigation) check against your spell save DC to find it. You decide what triggers the glyph when you cast the spell. For glyphs inscribed on a surface, the most typical triggers include touching or stepping on the glyph, removing another object covering it, approaching within a certain distance of it, or manipulating the object that holds it. For glyphs inscribed within an object, the most common triggers are opening the object, approaching within a certain distance of it, or seeing or reading the glyph. You can further refine the trigger so the spell is activated only under certain circumstances or according to a creature’s physical characteristics (such as height or weight), or physical kind (for example, the ward could be set to affect hags or shapechangers). You can also specify creatures that don’t trigger the glyph, such as those who say a certain password. When you inscribe the glyph, choose one of the following options for its effect. Once triggered, the glyph glows, filling a 60-foot-radius sphere with dim light for 10 minutes, after which time the spell ends. Each creature in the sphere when the glyph activates is targeted by its effect, as is a creature that enters the sphere for the first time on a turn or ends its turn there. Death. Each target must make a CON save, taking 10d10 necrotic damage on a failed save, or half as much damage on a successful save. Discord. Each target must make a CON save. On a failed save, a target bickers and argues with other creatures for 1 minute. During this time, it is incapable of meaningful communication and has disadvantage on attack rolls and ability checks. Fear. Each target must make a WIS save, becoming frightened for 1 minute on a failed save. While frightened, PLAYER'S GUIDE the target drops whatever it is holding and must move at least 30 feet away from the glyph on each of its turns, if able. Hopelessness. Each target must make a CHA save. On a failed save, the target is consumed with despair for 1 minute. During this time, it can’t attack or target any creature with harmful abilities, spells, or other magical effects. Overwhelm. Each target must make an INT save. On a failed save, the target is driven incapacitated for 1 minute. While incapacitated the target can’t take actions, can’t understand what other creatures say, can’t read, and speaks only in gibberish. The GM controls its movement, which is erratic. Pain. Each target must make a CON save, becoming incapacitated with excruciating pain for 1 minute on a failed save. Sleep. Each target must make a WIS save, falling unconscious for 10 minutes on a failed save. A creature awakens if it takes damage or if someone uses an action to shake or slap it awake. Stunning. Each target must make a WIS save, becoming stunned for 1 minute on a failed save."},{"name":"Teleportation Circle","circle":5,"sources":["Arcane"],"school":"Conjuration","text":"Casting Time: 1 minute Range: 10 feet Components: V, M (rare chalks and inks infused with precious gems worth 50 gp, which the spell consumes) Duration: 1 round You create a portal that allows you to teleport to a defined location. As you cast the spell, you draw a 10-foot-diameter circle on the ground inscribed with sigils that link your location to a permanent teleportation circle of your choice whose sigil sequence you know and that is on the same plane of existence as you. A shimmering portal opens within the circle you drew and remains open until the end of your next turn. Any creature that enters the portal instantly appears within 5 feet of the destination circle or in the nearest unoccupied space if that space is occupied. Many major temples, guilds, and other important places have permanent teleportation circles inscribed somewhere within their confines. Each such circle includes a unique sigil sequence—a string of magical runes arranged in a particular pattern. When you first gain the ability to cast this spell, you learn the sigil sequences for two destinations on the Material Plane, determined by the GM. You can learn additional sigil sequences during your adventures. You can commit a new sigil sequence to memory after studying it for 1 minute. You can create a permanent teleportation circle by casting this spell in the same location every day for one year. You need not use the circle to teleport when you cast the spell in this way."},{"name":"Tiny Hut","circle":3,"sources":["Arcane"],"school":"Evocation","text":"Casting Time: 10 minutes Range: Self (10-foot-radius dome) Components: V, S, M (a small crystal bead) Duration: 8 hours You create a protective dome to shield yourself and creatures near you. A 10-foot-radius, immobile dome of force springs into existence around and above you and remains stationary for the duration. The spell ends if you leave its area. Nine creatures of Medium size or smaller can fit inside the dome with you. The spell fails if its area includes a larger creature or more than nine creatures. Creatures and objects within the dome when you cast this spell can move through it freely. All other creatures and objects are barred from passing through it. Spells and other magical effects can’t extend through the dome or be cast through it. The atmosphere inside the space is comfortable and dry, regardless of the weather outside. Until the spell ends, you can command the interior to become dimly lit or dark. The dome is an opaque color of your choice from the outside, but it is transparent from the inside."},{"name":"Trestle","circle":3,"sources":["Primordial"],"school":"Conjuration","text":"Casting Time: 10 minutes Range: 30 feet Components: V, S, M (a 1-inch piece of green vine, which the spell consumes) Duration: Until destroyed or dispelled You empower a climbable vine to grow supernaturally quickly. You cause a vine to sprout from the ground and crawl across a surface or rise into the air in a direction you choose. The vine must sprout from a solid surface (such as the ground or a wall), and it is strong enough to support 600 pounds of weight along its entire length, which can be a number of feet up to 5 × the highest Primordial circle you have access to. The vine collapses immediately if the weight limit is exceeded. A vine that collapses from weight or damage instantly disintegrates. The vine has many small shoots that can be climbed with a successful DC 5 STR (Athletics) check. It has AC 8, hit points equal to 5 × the highest Primordial circle you have access to, and a damage threshold of 5. At Higher Circles. As you unlock higher circles, this ritual grows in potency. Once you have access to 4th-circle spell slots or higher, the vine can support an additional 30 pounds and its damage threshold increases by 1 for each slot you have access to above 3rd. 351"},{"name":"True Resurrection","circle":9,"sources":["Divine"],"school":"Necromancy","text":"Casting Time: 1 hour Range: Touch Components: V, S, M (a sprinkle of holy water and diamonds worth at least 25,000 gp, which the spell consumes) Duration: Instantaneous You bring a dead soul back to life and banish all diseases, curses, and ailments that affected them in life. You touch a creature that has been dead for no longer than 200 years and that died for any reason except old age. If the creature’s soul is free and willing, the creature is restored to life with all its hit points. This spell closes all wounds, neutralizes any poison, cures all diseases, and lifts any curses affecting the creature when it died. The spell replaces damaged or missing organs and limbs. The spell can even provide a new body if the original no longer exists, in which case you must speak the creature’s name. The creature then appears in an unoccupied space you choose within 10 feet of you."},{"name":"Unseen Servant","circle":1,"sources":["Arcane","Wyrd"],"school":"Conjuration","text":"Casting Time: 1 minute Range: 60 feet Components: V, S, M (a piece of string and a bit of wood) Duration: 1 hour You conjure an invisible servant to perform simple tasks for you. This spell creates an invisible, mindless, shapeless force that performs simple tasks at your command until the spell ends. The servant springs into existence in an unoccupied space on the ground within range. It has AC 10, 1 HP, a STR of 3 (−4), and it can’t attack. If it drops to 0 HP, the spell ends. Once on each of your turns as a bonus action, you can mentally command the servant to move up to 15 feet and interact with an object. The servant can perform simple tasks that a human servant could do, such as fetching things, cleaning, mending, folding clothes, lighting fires, serving food, and pouring wine. Once you give the command, the servant performs the task to the best of its ability until it completes the task, then waits for your next command. If you command the servant to perform a task that would move it more than 60 feet away from you, the spell ends. If you cast this spell again while a servant created by the first casting is still active, the servant created from the first casting is immediately destroyed."},{"name":"Water Walk","circle":3,"sources":["Primordial"],"school":"Transmutation","text":"Casting Time: 10 minutes Range: 30 feet Components: V, S, M (a piece of cork) Duration: 1 hour You grant creatures the ability to walk across liquid surfaces. This spell grants the ability to move across any liquid surface—water, acid, mud, snow, quicksand, or lava— as if it were harmless solid ground (creatures crossing molten lava can still take damage from the heat). Up to ten willing creatures you can see within range gain this ability for the duration. If you target a creature submerged in a liquid, the spell carries the target to the surface of the liquid at a rate of 60 feet per round."}]

/** Rituals available from a source at or below a maximum circle, sorted by name. */
export function ritualsFor(source: SpellSource, maxCircle: number): Ritual[] {
  return RITUALS.filter(
    (r) => r.sources.includes(source) && r.circle >= 1 && r.circle <= maxCircle,
  ).sort((a, b) => a.circle - b.circle || a.name.localeCompare(b.name))
}

export function getRitual(name: string): Ritual | undefined {
  return RITUALS.find((r) => r.name === name)
}
